SELECT r.*, m.material_name FROM material_report r
LEFT JOIN material m ON r.material_id = m.material_id
WHERE r.status = #{status}
ORDER BY r.create_time DESC, r.report_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT r.*, m.material_name FROM material_report r
LEFT JOIN material m ON r.material_id = m.material_id
WHERE r.reporter_id = #{reporterId}
ORDER BY r.create_time DESC, r.report_id DESC LIMIT #{limit} OFFSET #{offset}
